/**
 * Default OUT driver API
 */
RC_t SC_DISPLAY_driverOut(const SC_DISPLAY_data_t  *const data)
{
	/* USER CODE START driverOutSC_DISPLAY */
    
    static uint8_t init = 0;
    static int16_t oldTargetPixel  = 100;
    static int16_t oldCurrentPixel = 100;
    static int16_t oldErrorPixel   = 100;
    static uint16_t oldPixelX       = 0;
    
    
    if(init == 0 || oldPixelX == 126){
        TFT_fillRect(0,50,128,120,YELLOW);
        init = 1;
    }
   
    sint16_t CurrentSpeed = data->currentSpeed * data->currentDirection;
    sint16_t TargetSpeed  = data->targetSpeed  * data->targetDirection;

    TFT_setCursor(5, 5);
    TFT_printf("Joystick:%6d", data->joystick);
    
    TFT_setCursor(5, 20);
    TFT_printf("Current :%6d RPM", CurrentSpeed);

    TFT_setCursor(5, 35);
    TFT_printf("Target  :%6d RPM", TargetSpeed);
    
    
    int16_t targetPixel     = 100+((TargetSpeed * 110)/ 10000); 
    int16_t currentPixel    = 100+((CurrentSpeed * 110)/ 10000); 
    int16_t errorPixel      = 100+(((TargetSpeed - CurrentSpeed) * 110)/ 10000);
    
    if(data->pixelX >= oldPixelX){
        TFT_writeLine(oldPixelX, oldTargetPixel, data->pixelX, targetPixel, BLUE);
        TFT_writeLine(oldPixelX, oldCurrentPixel, data->pixelX, currentPixel, BLACK);
        TFT_writeLine(oldPixelX, oldErrorPixel, data->pixelX, errorPixel, RED);
    }
    oldTargetPixel  = targetPixel;
    oldCurrentPixel = currentPixel;
    oldErrorPixel   = errorPixel;
    oldPixelX       = data->pixelX;
   
	//Scale application data to drive format

	//Write scaled data to driver

	return RC_SUCCESS;
	/* USER CODE END driverOutSC_DISPLAY */
}



